    /** The parts the clips move, for the rig animator. */
    val RIG: List<String> = listOf("body", "neck", "head", "ear_r", "ear_l", "forelock", "mane", "tail", "tail_end", "collar", "bells", "fr_leg", "fr_shin", "fr_hoof", "fl_leg", "fl_shin", "fl_hoof", "hr_leg", "hr_shin", "hr_hoof", "hl_leg", "hl_shin", "hl_hoof", "trace_r_cut", "trace_l_cut", "rein_r_cut", "rein_l_cut", "nosebag")

    /**
     * Hidden unless wanted: "nosebag" (feeding at the stand), and the cut ends of the traces ("trace_r_cut",
     * "trace_l_cut") and reins ("rein_r_cut", "rein_l_cut") once it's cut loose or lies dead by the wreck.
     */
    val HIDDEN: List<String> = listOf("nosebag", "trace_r_cut", "trace_l_cut", "rein_r_cut", "rein_l_cut")

    /** A point on the horse: [x], [y], [z] (px) in the frame of [part] (from its pivot, turned with it). */
    class Point(val part: String, val x: Float, val y: Float, val z: Float)

    /** The bit's rings, where the reins start (the right one's x mirrored). At rest: 3.05f, -2.673f, -29.488f (model space). */
    val BIT_LEFT = Point("head", 3.05f, 3.3f, -12.1f)
    val BIT_RIGHT = Point("head", -3.05f, 3.3f, -12.1f)
    /** The rein rings on the saddle the reins run through (WagonMesh.TERRET). At rest: 2.2f, -7.4f, -4f. */
    val TERRET_LEFT = Point("body", 2.2f, -10.4f, -4f)
    val TERRET_RIGHT = Point("body", -2.2f, -10.4f, -4f)
    /** The tugs the shafts run through (WagonMesh.SHAFT_X, the shafts' middle line). At rest: 8.2f, 3f, -4f. */
    val TUG_LEFT = Point("body", 8.2f, 0f, -4f)
    val TUG_RIGHT = Point("body", -8.2f, 0f, -4f)
    /** The hame hooks, the traces' front ends (WagonMesh.HAMES). At rest: 7f, 3f, -20.369f. */
    val HAME_LEFT = Point("collar", 7f, 6.668f, -2.35f)
    val HAME_RIGHT = Point("collar", -7f, 6.668f, -2.35f)

    /** Blocks it goes in one loop of "walk" (and "strain") and of "bolt": play them by distance. */
    const val WALK_STRIDE = 1.8f
    const val BOLT_STRIDE = 4.2f

    /**
     * Something to hear on a clip's tick: "hoof" (a hoof down at the walk or the bolt), "stamp", "snort", "neigh",
     * "thud" (it comes down on the ground) or "tear" (a mouthful of grass torn up).
     */
    class Moment(val tick: Float, val what: String)

    val MOMENTS: Map<String, List<Moment>> = mapOf(
        "idle" to listOf(Moment(60f, "snort"), Moment(157f, "stamp"), Moment(162.5f, "stamp")),
